-- Phase 11 final features and removal of runtime schema mutation
CREATE TABLE IF NOT EXISTS `reseller_ticket_attachments` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`tracking` VARCHAR(100) NOT NULL,`reseller_id` VARCHAR(64) NOT NULL,`uploader_type` VARCHAR(20) NOT NULL,`uploader_id` VARCHAR(64) NOT NULL,`storage_name` VARCHAR(500) NOT NULL,`original_name` VARCHAR(191) NOT NULL,`mime_type` VARCHAR(100) NOT NULL,`file_size` BIGINT UNSIGNED NOT NULL,`sha256` CHAR(64) NOT NULL,`created_at` BIGINT UNSIGNED NOT NULL,KEY `idx_rta_ticket` (`tracking`,`reseller_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `reseller_payout_accounts` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`reseller_id` VARCHAR(64) NOT NULL,`holder_name` VARCHAR(191) NOT NULL,`iban_cipher` TEXT NOT NULL,`iban_last4` CHAR(4) NOT NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'pending',`is_active` TINYINT(1) NOT NULL DEFAULT 1,`verified_by` VARCHAR(191) NULL,`verified_at` BIGINT UNSIGNED NULL,`created_at` BIGINT UNSIGNED NOT NULL,KEY `idx_rpa_owner` (`reseller_id`,`is_active`,`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `reseller_settlement_settings` (`id` TINYINT UNSIGNED PRIMARY KEY,`enabled` TINYINT(1) NOT NULL DEFAULT 0,`min_amount` BIGINT UNSIGNED NOT NULL DEFAULT 100000,`fee_percent` DECIMAL(5,2) NOT NULL DEFAULT 0,`hold_hours` INT UNSIGNED NOT NULL DEFAULT 24,`updated_at` BIGINT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `reseller_settlement_settings` (`id`) VALUES (1);
CREATE TABLE IF NOT EXISTS `reseller_settlements` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`request_id` CHAR(32) NOT NULL,`reseller_id` VARCHAR(64) NOT NULL,`payout_account_id` BIGINT UNSIGNED NOT NULL,`amount` BIGINT UNSIGNED NOT NULL,`fee` BIGINT UNSIGNED NOT NULL DEFAULT 0,`net_amount` BIGINT UNSIGNED NOT NULL,`status` VARCHAR(20) NOT NULL,`idempotency_key` VARCHAR(100) NOT NULL,`requested_at` BIGINT UNSIGNED NOT NULL,`reviewed_at` BIGINT UNSIGNED NULL,`reviewed_by` VARCHAR(191) NULL,`paid_at` BIGINT UNSIGNED NULL,`paid_by` VARCHAR(191) NULL,`payment_reference` VARCHAR(191) NULL,`admin_note` VARCHAR(1000) NULL,UNIQUE KEY `uq_rs_request` (`request_id`),UNIQUE KEY `uq_rs_idem` (`idempotency_key`),KEY `idx_rs_owner_status` (`reseller_id`,`status`,`requested_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `reseller_product_categories` (`reseller_id` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`product_code` VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`category_id` BIGINT UNSIGNED NOT NULL,`created_at` BIGINT UNSIGNED NOT NULL,PRIMARY KEY (`reseller_id`,`product_code`),KEY `idx_rpc_category` (`reseller_id`,`category_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `reseller_api_nonces` (`api_key_id` BIGINT UNSIGNED NOT NULL,`nonce` VARCHAR(100) NOT NULL,`used_at` BIGINT UNSIGNED NOT NULL,PRIMARY KEY (`api_key_id`,`nonce`),KEY `idx_ran_time` (`used_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `reseller_api_idempotency` (`api_key_id` BIGINT UNSIGNED NOT NULL,`idempotency_key` VARCHAR(100) NOT NULL,`endpoint` VARCHAR(100) NOT NULL,`request_hash` CHAR(64) NOT NULL,`status_code` INT NULL,`response_body` MEDIUMTEXT NULL,`created_at` BIGINT UNSIGNED NOT NULL,`completed_at` BIGINT UNSIGNED NULL,PRIMARY KEY (`api_key_id`,`idempotency_key`),KEY `idx_rai_time` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `crypto_wallets` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`currency` VARCHAR(20) NOT NULL,`network` VARCHAR(20) NOT NULL,`wallet_address` VARCHAR(255) NOT NULL,`label` VARCHAR(255) NULL,`enabled` TINYINT(1) NOT NULL DEFAULT 1,`min_irt` BIGINT NOT NULL DEFAULT 20000,`max_irt` BIGINT NOT NULL DEFAULT 100000000,`cashback_percent` DECIMAL(6,2) NOT NULL DEFAULT 0,`rate_irt_override` DECIMAL(20,4) NULL,`wallet_memo` VARCHAR(255) NULL,`created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY `uq_cw_currency` (`currency`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `app` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`name` VARCHAR(200) NOT NULL,`link` VARCHAR(500) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `shopSetting` (`Namevalue` VARCHAR(191) PRIMARY KEY,`value` TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `processed_updates` (`update_id` BIGINT UNSIGNED PRIMARY KEY,`processed_at` INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `flash_campaigns` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`title` VARCHAR(500) NOT NULL,`discount_percent` INT NOT NULL DEFAULT 0,`product_filter` TEXT NULL,`starts_at` VARCHAR(50) NOT NULL,`ends_at` VARCHAR(50) NOT NULL,`is_active` TINYINT(1) NOT NULL DEFAULT 1,`notify_sent` TINYINT(1) NOT NULL DEFAULT 0,`created_at` VARCHAR(50) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `audit_log` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`admin_user` VARCHAR(200) NULL,`action` VARCHAR(200) NOT NULL,`entity` VARCHAR(200) NULL,`details` TEXT NULL,`ip` VARCHAR(100) NULL,`created_at` VARCHAR(50) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `channels` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`remark` VARCHAR(200) NULL,`linkjoin` VARCHAR(200) NULL,`link` VARCHAR(200) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `cron_runtime_state` (`job_key` VARCHAR(191) PRIMARY KEY,`last_run` BIGINT UNSIGNED NOT NULL DEFAULT 0,`unit` VARCHAR(20) NOT NULL DEFAULT 'minute',`value` INT UNSIGNED NOT NULL DEFAULT 1,`enabled` TINYINT(1) NOT NULL DEFAULT 1,`created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `x_ui` (`codepanel` VARCHAR(100) PRIMARY KEY,`setting` LONGTEXT NOT NULL,`protocol` VARCHAR(100) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `reseller_cards` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`reseller_id` VARCHAR(200) NOT NULL,`cardnumber` VARCHAR(500) NOT NULL,`namecard` VARCHAR(1000) NOT NULL,KEY `idx_rc_owner` (`reseller_id`(191))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `reseller_ai_feature` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`reseller_id` VARCHAR(200) NOT NULL,`bot_token` VARCHAR(500) NOT NULL,`bot_username` VARCHAR(200) NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'disabled',`activated_at` VARCHAR(50) NULL,`expires_at` VARCHAR(50) NULL,`days` INT NOT NULL DEFAULT 30,`price_paid` INT NOT NULL DEFAULT 0,`notes` TEXT NULL,`created_at` VARCHAR(50) NULL,`updated_at` VARCHAR(50) NULL,UNIQUE KEY `uq_raf_token` (`bot_token`(191))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `rx_user_cache` (`id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`user_id` VARCHAR(200) NOT NULL,`invoice_id` VARCHAR(200) NOT NULL,`username` VARCHAR(300) NULL,`panel_name` VARCHAR(300) NULL,`panel_type` VARCHAR(50) NULL,`expire_ts` BIGINT NOT NULL DEFAULT 0,`used_traffic` BIGINT NOT NULL DEFAULT 0,`data_limit` BIGINT NOT NULL DEFAULT 0,`status` VARCHAR(50) NULL,`enabled` TINYINT(1) NOT NULL DEFAULT 1,`online` TINYINT(1) NOT NULL DEFAULT 0,`sub_url` TEXT NULL,`synced_at` VARCHAR(50) NULL,UNIQUE KEY `uq_rxc_invoice` (`invoice_id`(191))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `nm_config_stock` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`shelf_id` BIGINT UNSIGNED NULL,`codepanel` VARCHAR(191) NOT NULL DEFAULT 'auto',`codeproduct` VARCHAR(191) NOT NULL DEFAULT 'auto',`tier` VARCHAR(32) NOT NULL DEFAULT 'auto',`format` VARCHAR(32) NOT NULL DEFAULT 'link',`content` MEDIUMTEXT NOT NULL,`sub_link` MEDIUMTEXT NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'active',`assigned_user` VARCHAR(64) NULL,`assigned_invoice` VARCHAR(64) NULL,`assigned_mode` VARCHAR(64) NULL,`created_at` INT UNSIGNED NOT NULL DEFAULT 0,`reserved_at` INT UNSIGNED NULL,`delivered_at` INT UNSIGNED NULL,UNIQUE KEY `uq_nm_content` (`content`(191)),KEY `idx_nm_lookup` (`status`,`codepanel`(63),`codeproduct`(63),`tier`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `nm_stock_shelves` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`name` VARCHAR(191) NOT NULL,`source_codepanel` VARCHAR(191) NOT NULL DEFAULT 'auto',`stock_codepanel` VARCHAR(191) NOT NULL DEFAULT 'auto',`category_id` VARCHAR(64) NULL,`category_name` VARCHAR(191) NULL,`codeproduct` VARCHAR(191) NOT NULL DEFAULT 'auto',`product_name` VARCHAR(191) NULL,`volume_gb` DECIMAL(10,2) NOT NULL DEFAULT 0,`service_days` INT NOT NULL DEFAULT 0,`price` BIGINT NOT NULL DEFAULT 0,`status` VARCHAR(20) NOT NULL DEFAULT 'active',`created_at` INT UNSIGNED NOT NULL DEFAULT 0,`updated_at` INT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `nm_config_stock_log` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`stock_id` BIGINT UNSIGNED NULL,`id_user` VARCHAR(64) NULL,`id_invoice` VARCHAR(64) NULL,`action` VARCHAR(64) NOT NULL,`payload` MEDIUMTEXT NULL,`created_at` INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `nm_stock_product_map` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`source_codepanel` VARCHAR(191) NOT NULL DEFAULT 'auto',`stock_codepanel` VARCHAR(191) NOT NULL DEFAULT 'auto',`codeproduct` VARCHAR(191) NOT NULL DEFAULT 'auto',`category` VARCHAR(191) NULL,`category_id` VARCHAR(64) NULL,`category_name` VARCHAR(191) NULL,`volume_gb` DECIMAL(10,2) NOT NULL DEFAULT 0,`service_days` INT NOT NULL DEFAULT 0,`price` BIGINT NOT NULL DEFAULT 0,`status` VARCHAR(20) NOT NULL DEFAULT 'active',`created_at` INT UNSIGNED NOT NULL DEFAULT 0,`updated_at` INT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @db:=DATABASE();
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='reseller_api_keys' AND COLUMN_NAME='ip_allowlist')=0,'ALTER TABLE reseller_api_keys ADD COLUMN ip_allowlist TEXT NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='reseller_categories' AND COLUMN_NAME='slug')=0,'ALTER TABLE reseller_categories ADD COLUMN slug VARCHAR(191) NULL,ADD COLUMN sort_order INT NOT NULL DEFAULT 0,ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT ''active'',ADD COLUMN updated_at BIGINT UNSIGNED NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
UPDATE reseller_categories SET slug=CONCAT('rc-',id),updated_at=COALESCE(updated_at,created_at) WHERE slug IS NULL OR slug='';
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='user' AND COLUMN_NAME='auto_renew')=0,'ALTER TABLE user ADD COLUMN auto_renew TINYINT(1) NOT NULL DEFAULT 0','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='user' AND COLUMN_NAME='nm_shelf_active')=0,'ALTER TABLE user ADD COLUMN nm_shelf_active VARCHAR(32) NULL,ADD COLUMN nm_stock_session TEXT NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='invoice' AND COLUMN_NAME='source_panel_code')=0,'ALTER TABLE invoice ADD COLUMN source_panel_code VARCHAR(191) NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='marzban_panel' AND COLUMN_NAME='health_status')=0,'ALTER TABLE marzban_panel ADD COLUMN health_status VARCHAR(20) DEFAULT ''unknown'',ADD COLUMN last_health_check VARCHAR(50) NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='setting' AND COLUMN_NAME='ai_support')=0,'ALTER TABLE setting ADD COLUMN ai_support TEXT NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='setting' AND COLUMN_NAME='daily_reward_status')=0,'ALTER TABLE setting ADD COLUMN daily_reward_status VARCHAR(100) NULL,ADD COLUMN daily_reward_amount VARCHAR(100) NULL,ADD COLUMN daily_reward_streak_bonus VARCHAR(100) NULL,ADD COLUMN daily_reward_max_streak VARCHAR(100) NULL,ADD COLUMN upsell_status VARCHAR(100) NULL,ADD COLUMN winback_status VARCHAR(100) NULL,ADD COLUMN winback_days VARCHAR(100) NULL,ADD COLUMN winback_discount VARCHAR(100) NULL,ADD COLUMN channel_autopost_status VARCHAR(100) NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='setting' AND COLUMN_NAME='reseller_ai_price')=0,'ALTER TABLE setting ADD COLUMN reseller_ai_price VARCHAR(100) NOT NULL DEFAULT ''0'',ADD COLUMN reseller_ai_days VARCHAR(20) NOT NULL DEFAULT ''30''','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='setting' AND COLUMN_NAME='renewal_reminder_status')=0,'ALTER TABLE setting ADD COLUMN renewal_reminder_status VARCHAR(10) DEFAULT ''on'',ADD COLUMN renewal_reminder_days VARCHAR(50) DEFAULT ''3,1'',ADD COLUMN auto_renew_status VARCHAR(10) DEFAULT ''off'',ADD COLUMN volume_warn_status VARCHAR(10) DEFAULT ''on''','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='botsaz' AND COLUMN_NAME='bot_status')=0,'ALTER TABLE botsaz ADD COLUMN bot_expires_at VARCHAR(50) NULL,ADD COLUMN bot_status VARCHAR(30) DEFAULT ''active'',ADD COLUMN bot_charge_amount VARCHAR(100) DEFAULT ''0''','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='marzban_panel' AND COLUMN_NAME='emergency_panel_status')=0,'ALTER TABLE marzban_panel ADD COLUMN emergency_panel_status VARCHAR(50) DEFAULT ''off_emergency_panel'',ADD COLUMN national_net_status VARCHAR(50) DEFAULT ''off_national_net'',ADD COLUMN emergency_source_panel VARCHAR(191) NULL,ADD COLUMN stock_source_panel VARCHAR(191) NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
